"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8598],{87879:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"Bezier","desc":"Third-party bezier curve module for easy creation of bezier curves. Created by\\nbhristt (october 15 2021, updated october 25 2021) and vendored here largely\\nunmodified.\\n\\nA curve is built from control points that may be [Vector3]s or [BasePart]s; parts\\nare tracked, so moving one reshapes the curve. Points are managed with\\n`AddBezierPoint`, `ChangeBezierPoint`, `RemoveBezierPoint`, `GetPoint` and\\n`GetAllPoints`.\\n\\nPositions and derivatives can be sampled two ways. The `...At` methods take the\\nraw curve parameter, which is not evenly spaced along the curve; the\\n`...RelativeToLength` methods take a fraction of arc length, which is what you\\nwant for constant-speed movement. Arc length is approximated over\\n`LengthIterations` samples and refreshed by `UpdateLength`.\\n\\n`CreateVector3Tween` and `CreateCFrameTween` drive an instance along the curve,\\nand `Destroy` releases the part connections.\\n\\nThis is vendored code \u2014 read the source for per-method detail rather than\\nexpecting firebit-style docs on all 14 methods.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":28,"path":"src/Shared/Class/Bezier.luau"}}')}}]);